===== Cp10 =====


/** household-duplicate: the household is keyed by the computed householdId
 * (lastName + postcode). Two owners with the same lastName + postcode collide with 409 (no
 * sharesHousehold), even with different addresses. */
@Tag("cp10")
class Cp10Tests extends AcceptanceBase {

	@Test
	void coreSameLastNameAndPostcodeRejected() throws Exception {
		String lastName = uniqueLastName();
		ObjectNode a = ownerNode();
		a.put("lastName", lastName);
		a.put("postcode", "2000");
		createOwnerOk(a);
		ObjectNode b = ownerNode(); // same lastName + postcode, different address/telephone
		b.put("lastName", lastName);
		b.put("postcode", "2000");
		createOwner(b).andExpect(status().isConflict());
	}
}
===== Cp11 =====


/** shares-household: householdId is computed from lastName + postcode, so
 * sharesHousehold only bypasses the block. Two same lastName+postcode owners share the householdId. */
@Tag("cp11")
class Cp11Tests extends AcceptanceBase {

	@Test
	void coreComputedHouseholdIdShared() throws Exception {
		String lastName = uniqueLastName();
		ObjectNode a = ownerNode();
		a.put("lastName", lastName);
		a.put("postcode", "2000");
		int ida = createOwnerOk(a);
		ObjectNode b = ownerNode();
		b.put("lastName", lastName);
		b.put("postcode", "2000");
		b.put("sharesHousehold", true); // bypass the duplicate block
		int idb = createOwnerOk(b);
		assertEquals(fetchOwner(ida).get("householdId").asText(),
				fetchOwner(idb).get("householdId").asText());
	}
}
===== Cp25 =====


/** email-unique: the email duplicate check is expressed through the identityKey
 * (which includes the email). A repeated full identity, email and all, collides with 409. */
@Tag("cp25")
class Cp25Tests extends AcceptanceBase {

	@Test
	void coreEmailIdentityCollisionRejected() throws Exception {
		ObjectNode a = ownerNode();
		a.put("email", uniqueEmail());
		createOwnerOk(a);
		// A pure full duplicate (email included) must collide (409). No sharesHousehold tweak, which
		// would de-sync the householdId and let the keys differ before makes householdId computed.
		createOwner(a.deepCopy()).andExpect(status().isConflict());
	}
}
===== Cp28 =====


/** identity-key: the identityKey now uses the computed householdId. A repeated
 * full identity (same telephone / household) still collides with 409. */
@Tag("cp28")
class Cp28Tests extends AcceptanceBase {

	@Test
	void coreIdentityCollisionWithComputedHousehold() throws Exception {
		ObjectNode a = ownerNode();
		a.put("postcode", "2000");
		createOwnerOk(a);
		ObjectNode b = a.deepCopy(); // same telephone / lastName / postcode -> same householdId + identityKey
		b.put("sharesHousehold", true);
		createOwner(b).andExpect(status().isConflict());
	}
}
===== Cp35 =====


/** soft-match: the soft-match key (lastName + postcode) is now exactly the
 * household key, so that pair is a household rather than a soft match. A second owner sharing
 * lastName and postcode is a household duplicate (409) unless it declares sharesHousehold, in which
 * case it is created as a household member and is NOT flagged a possible duplicate. (The soundex
 * soft-match returns at , once the household block is folded into the identity key.) */
@Tag("cp35")
class Cp35Tests extends AcceptanceBase {

	@Test
	void coreSharedLastNameAndPostcodeIsHouseholdDuplicate() throws Exception {
		String lastName = uniqueLastName();
		ObjectNode a = ownerNode();
		a.put("lastName", lastName);
		a.put("postcode", "2000");
		createOwnerOk(a);
		ObjectNode b = ownerNode(); // same lastName + postcode, no sharesHousehold -> household duplicate
		b.put("lastName", lastName);
		b.put("postcode", "2000");
		createOwner(b).andExpect(status().isConflict());
	}

	@Test
	void functionalityDeclaredHouseholdMemberNotFlagged() throws Exception {
		String lastName = uniqueLastName();
		ObjectNode a = ownerNode();
		a.put("lastName", lastName);
		a.put("postcode", "2000");
		createOwnerOk(a);
		ObjectNode b = ownerNode();
		b.put("lastName", lastName);
		b.put("postcode", "2000");
		b.put("sharesHousehold", true); // declared member -> created, not a suspected duplicate
		int id = createOwnerOk(b);
		getOwner(id).andExpect(jsonPath("$.possibleDuplicate").value(false));
	}
}
===== Cp36 =====


/** household-hash: the household hash reads the structured postcode. Two
 * structured owners with the same lastName + postcode share a householdId. */
@Tag("cp36")
class Cp36Tests extends AcceptanceBase {

	@Test
	void coreHouseholdIdFromStructuredPostcode() throws Exception {
		String lastName = uniqueLastName();
		ObjectNode a = structuredOwner();
		a.put("lastName", lastName);
		a.put("postcode", "2000");
		ObjectNode b = structuredOwner();
		b.put("lastName", lastName);
		b.put("postcode", "2000");
		b.put("sharesHousehold", true);
		assertEquals(fetchOwner(createOwnerOk(a)).get("householdId").asText(),
				fetchOwner(createOwnerOk(b)).get("householdId").asText());
	}
}
===== Cp03 =====


/** telephone-unique: duplicate detection is now the single identityKey
 * (telephone|email|householdId). Two owners with the same identity collide with 409. */
@Tag("cp03")
class Cp03Tests extends AcceptanceBase {

	@Test
	void coreIdentityCollisionRejected() throws Exception {
		ObjectNode a = ownerNode();
		createOwnerOk(a);
		// A pure full duplicate: identical in every identity-bearing field, so it must collide (409)
		// under every later version of the key. Do NOT tweak b (e.g. sharesHousehold), which would
		// de-sync the householdId and let the keys differ before makes householdId computed.
		createOwner(a.deepCopy()).andExpect(status().isConflict());
	}
}

